AActor* ACAIController::GetNextPerceivedActor() const
{
	if (PerceptionComponent)
	{
		// 存储感知到的Actor
		TArray<AActor*> Actors;
		// 获取感知到的敌对Actor并存储到数组中
		AIPerceptionComponent->GetPerceivedHostileActors(Actors);

		// 如果敌对Actor的数量不为零
		if (Actors.Num() != 0)
		{
			// 返回第一个
			return Actors[0];
		}
	}

